import { Link } from "react-router-dom";
import "./Header.scss";

const Header = () => {
  return (
    <header className="header">
      <div className="header__race">nextrace</div>
      <div className="header__logo">logo</div>
      <div className="header__buttons">
        <Link className="header-button__login" />
        <Link className="header-button__signup" />
      </div>
    </header>
  );
};

export default Header;
